/// 活动类型 (per 9/4 MD §4 反例: 不写 9 套 holiday_* 重复)
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ActivityType {
    Unspecified,
    Holiday,
    Signin,
    Achievement,
    Battlepass,
    Return,
    Invite,
    LevelReward,
    Daily,
    Weekly,
}

impl ActivityType {
    pub fn from_i32(v: i32) -> Self {
        match v {
            1 => Self::Holiday,
            2 => Self::Signin,
            3 => Self::Achievement,
            4 => Self::Battlepass,
            5 => Self::Return,
            6 => Self::Invite,
            7 => Self::LevelReward,
            8 => Self::Daily,
            9 => Self::Weekly,
            _ => Self::Unspecified,
        }
    }
    pub fn as_i32(self) -> i32 {
        match self {
            Self::Unspecified => 0,
            Self::Holiday => 1,
            Self::Signin => 2,
            Self::Achievement => 3,
            Self::Battlepass => 4,
            Self::Return => 5,
            Self::Invite => 6,
            Self::LevelReward => 7,
            Self::Daily => 8,
            Self::Weekly => 9,
        }
    }
}

